
import React, { useState, useEffect } from 'react';
import { LOGO_SVG } from '../constants';
import { AppSection } from '../types';

interface NavbarProps {
  activeSection: AppSection;
  setActiveSection: (section: AppSection) => void;
}

const Navbar: React.FC<NavbarProps> = ({ activeSection, setActiveSection }) => {
  const [isScrolled, setIsScrolled] = useState(false);
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [discoverDropdownOpen, setDiscoverDropdownOpen] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 20);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const navItems = [
    { id: AppSection.HOME, label: 'HOME' },
    { id: AppSection.ABOUT, label: 'ABOUT US' },
    { 
      id: AppSection.SAFARI, 
      label: 'DISCOVER', 
      isDropdown: true,
      subItems: [
        { id: AppSection.ACCOMMODATION, label: 'ACCOMMODATION' },
        { id: AppSection.FOOD_AND_DRINKS, label: 'FOOD AND DRINKS' },
        { id: AppSection.EXPERIENCES, label: 'EXPERIENCES & EXCURSIONS' },
      ]
    },
    { id: AppSection.TOUR_PLANNER, label: 'TOUR PLANNER' },
    { id: AppSection.BLOG, label: 'BLOG' },
    { id: AppSection.CONTACT_US, label: 'CONTACT US' },
  ];

  const handleNavClick = (id: AppSection) => {
    setActiveSection(id);
    setMobileMenuOpen(false);
    setDiscoverDropdownOpen(false);
  };

  return (
    <>
      <nav 
        className={`fixed top-0 left-0 w-full z-[100] transition-all duration-500 ease-in-out ${
          isScrolled 
            ? 'bg-[#064E3B]/95 backdrop-blur-md shadow-2xl py-2' 
            : 'bg-transparent py-6'
        }`}
      >
        <div className="container mx-auto px-6 flex items-center justify-between">
          <div 
            className="flex items-center gap-3 cursor-pointer shrink-0" 
            onClick={() => handleNavClick(AppSection.HOME)}
          >
            <div className={`transition-all duration-500 ${isScrolled ? 'w-12 h-12 lg:w-16 lg:h-16' : 'w-20 h-20 lg:w-24 lg:h-24'}`}>
              {LOGO_SVG}
            </div>
          </div>
          
          <div className="hidden lg:flex gap-6 xl:gap-10 items-center">
            {navItems.map((item, idx) => (
              <div 
                key={idx} 
                className="relative group"
                onMouseEnter={() => item.isDropdown && setDiscoverDropdownOpen(true)}
                onMouseLeave={() => item.isDropdown && setDiscoverDropdownOpen(false)}
              >
                <button
                  onClick={() => !item.isDropdown && handleNavClick(item.id)}
                  className={`text-[11px] xl:text-[12px] font-bold tracking-[0.2em] transition-all uppercase relative flex items-center gap-2 ${
                    activeSection === item.id || (item.subItems?.some(si => si.id === activeSection)) ? 'text-emerald-400' : 'text-white/90 hover:text-white'
                  }`}
                >
                  {item.label}
                  {item.isDropdown && <i className={`fa-solid fa-chevron-down text-[8px] transition-transform ${discoverDropdownOpen ? 'rotate-180' : ''}`}></i>}
                  <span className={`absolute -bottom-2 left-0 h-[1.5px] transition-all duration-300 bg-emerald-400 ${
                    activeSection === item.id || (item.subItems?.some(si => si.id === activeSection)) ? 'w-full' : 'w-0 group-hover:w-full'
                  }`}></span>
                </button>

                {item.isDropdown && (
                  <div className={`absolute top-full left-0 mt-4 bg-[#064E3B] border border-white/10 shadow-2xl rounded-lg py-4 min-w-[240px] transition-all duration-300 ${discoverDropdownOpen ? 'opacity-100 visible translate-y-0' : 'opacity-0 invisible translate-y-4'}`}>
                    {item.subItems?.map((sub, sidx) => (
                      <button
                        key={sidx}
                        onClick={() => handleNavClick(sub.id)}
                        className={`w-full text-left px-6 py-3 text-[10px] font-bold tracking-widest uppercase hover:bg-emerald-800 transition-colors ${activeSection === sub.id ? 'text-emerald-400' : 'text-white/80'}`}
                      >
                        {sub.label}
                      </button>
                    ))}
                  </div>
                )}
              </div>
            ))}
          </div>

          <div className="flex items-center gap-4">
            <button 
              onClick={() => handleNavClick(AppSection.BOOKING)}
              className="hidden sm:block bg-emerald-600 text-white px-6 lg:px-10 py-3 lg:py-4 font-bold text-[10px] lg:text-xs hover:bg-emerald-500 transition-all uppercase tracking-[0.2em] shadow-xl active:scale-95 whitespace-nowrap"
            >
              BOOK NOW
            </button>
            
            <button 
              onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
              className="lg:hidden text-white p-2 focus:outline-none"
              aria-label="Toggle Menu"
            >
              <i className={`fa-solid ${mobileMenuOpen ? 'fa-xmark' : 'fa-bars'} text-2xl`}></i>
            </button>
          </div>
        </div>
      </nav>

      <div 
        className={`fixed inset-0 bg-[#064E3B] z-[90] transition-transform duration-500 ease-in-out transform ${
          mobileMenuOpen ? 'translate-x-0' : 'translate-x-full'
        } lg:hidden flex flex-col items-center justify-center p-10 overflow-y-auto`}
      >
        <div className="flex flex-col items-center gap-6 py-20">
          {navItems.map((item, idx) => (
            <div key={idx} className="flex flex-col items-center gap-4">
              <button
                onClick={() => !item.isDropdown && handleNavClick(item.id)}
                className={`text-lg font-bold tracking-[0.3em] uppercase transition-all ${
                  activeSection === item.id ? 'text-emerald-400' : 'text-white'
                }`}
              >
                {item.label}
              </button>
              {item.isDropdown && (
                <div className="flex flex-col items-center gap-3 opacity-80">
                  {item.subItems?.map((sub, sidx) => (
                    <button
                      key={sidx}
                      onClick={() => handleNavClick(sub.id)}
                      className={`text-sm font-medium tracking-[0.2em] uppercase transition-all ${
                        activeSection === sub.id ? 'text-emerald-400' : 'text-white/60'
                      }`}
                    >
                      {sub.label}
                    </button>
                  ))}
                </div>
              )}
            </div>
          ))}
          <button 
            onClick={() => handleNavClick(AppSection.BOOKING)}
            className="bg-emerald-600 text-white px-12 py-5 font-bold text-sm uppercase tracking-[0.3em] mt-6"
          >
            BOOK NOW
          </button>
        </div>
      </div>
    </>
  );
};

export default Navbar;
